<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};
final class ResponseTransportService
{
 use DeliveryOperations;
 public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly SiteAccessService $access,private readonly ControlRoomService $control) {}
 private function alarm(string $id):array {$r=$this->row('alarm_responses','alarm_id',$id);$this->access->requireSite($r['site_id']);$i=$this->row('incidents','incident_id',$r['incident_id']);if(!empty($i['deleted_at'])||(string)$i['site_id']!==(string)$r['site_id'])throw HttpException::notFound();return $r;}
 public function alarms(array $in):array {$this->fields($in,['site_id']);$s=$this->access->requireSite($in['site_id']??null);$rows=$this->db->fetchAll('SELECT a.* FROM alarm_responses a JOIN incidents i ON i.company_id=a.company_id AND i.incident_id=a.incident_id AND i.site_id=a.site_id WHERE a.company_id=:company AND a.site_id=:site AND i.deleted_at IS NULL ORDER BY alarm_id DESC LIMIT 300',['company'=>$this->company(),'site'=>$s['site_id']]);foreach($rows as&$r){$r['dispatch']=$r['dispatch_id']?$this->row('dispatch_jobs','dispatch_id',$r['dispatch_id']):null;$r['response_seconds']=$r['dispatch']&&$r['dispatch']['arrived_at']?max(0,strtotime($r['dispatch']['arrived_at'].' UTC')-strtotime($r['received_at'].' UTC')):null;$r['history']=$this->events('alarm',$r['alarm_id']);}return $rows;}
 public function createAlarm(array $in):array {return $this->atomic(function()use($in){$this->fields($in,['incident_id','source_reference','received_at']);$i=$this->row('incidents','incident_id',$in['incident_id']??null);$this->access->requireSite($i['site_id']);$at=$this->at($in['received_at']??null);if(!empty($i['deleted_at'])||in_array($i['status'],['CLOSED','CANCELLED','RESOLVED'],true)||strtotime($at.' UTC')>time()||strtotime($at.' UTC')<time()-30*86400)throw HttpException::unprocessable('Choose an open incident and alarm receipt within the last 30 days.');$ref=$this->text($in['source_reference']??null,150);if($this->db->fetch('SELECT alarm_id FROM alarm_responses WHERE company_id=:company AND site_id=:site AND source_reference=:ref',['company'=>$this->company(),'site'=>$i['site_id'],'ref'=>$ref]))throw HttpException::conflict('Alarm reference already recorded.');$this->db->execute('INSERT INTO alarm_responses(company_id,site_id,incident_id,source_reference,received_at) VALUES(:company,:site,:incident,:ref,:at)',['company'=>$this->company(),'site'=>$i['site_id'],'incident'=>$i['incident_id'],'ref'=>$ref,'at'=>$at]);$r=$this->created('alarm_response');$this->history('alarm',$r['id'],'RECEIVED',$ref);return $r;});}
 public function alarmAction(string $id,string $action,array $in):array {return $this->atomic(function()use($id,$action,$in){$this->fields($in,$action==='dispatch'?['expected_revision','responder_user_id','response_due_at']:['expected_revision','outcome','false_alarm_cause','notes']);$r=$this->alarm($id);$this->revision($r,$in);if($r['closed_at'])throw HttpException::conflict('Alarm already closed.');if($action==='dispatch'){if($r['dispatch_id'])throw HttpException::conflict('Dispatch already linked.');$this->operator($in['responder_user_id']??null,$r['site_id'],'alarm_response.self');$d=$this->control->createDispatch(['incident_id'=>$r['incident_id'],'responder_user_id'=>$in['responder_user_id'],'response_due_at'=>$in['response_due_at']??null]);$this->db->execute('UPDATE alarm_responses SET dispatch_id=:dispatch,revision=revision+1 WHERE company_id=:company AND alarm_id=:id',['dispatch'=>$d['id'],'company'=>$this->company(),'id'=>$id]);$this->history('alarm',$id,'DISPATCHED','Dispatch #'.$d['id']);return $d;}if($action!=='close')throw HttpException::notFound();$outcome=$in['outcome']??null;if(!in_array($outcome,['CONFIRMED','FALSE_ALARM','CANCELLED'],true))throw HttpException::unprocessable('Choose an alarm outcome.');$d=$r['dispatch_id']?$this->row('dispatch_jobs','dispatch_id',$r['dispatch_id']):null;$notes=$this->text($in['notes']??null,1000);if($outcome==='CANCELLED'){if($d&&!in_array($d['state'],['CANCELLED','CLOSED'],true))$this->control->dispatchAction((string)$d['dispatch_id'],'cancel',['expected_revision'=>$d['revision'],'resolution'=>$notes]);}else{if(!$d||$d['state']!=='ARRIVED')throw HttpException::conflict('Record responder arrival before closing a confirmed/false alarm.');$this->control->dispatchAction((string)$d['dispatch_id'],'close',['expected_revision'=>$d['revision'],'resolution'=>$notes]);}$cause=$outcome==='FALSE_ALARM'?$this->text($in['false_alarm_cause']??null,1000):null;$this->db->execute('UPDATE alarm_responses SET outcome=:outcome,false_alarm_cause=:cause,resolution=:notes,closed_at=:now,revision=revision+1 WHERE company_id=:company AND alarm_id=:id',['outcome'=>$outcome,'cause'=>$cause,'notes'=>$notes,'now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'id'=>$id]);$this->history('alarm',$id,'CLOSED',$outcome.': '.$notes);return ['closed'=>true];});}
 public function responder(array $in):array {$this->fields($in,[]);$rows=$this->db->fetchAll("SELECT a.*,d.state AS dispatch_state,d.revision AS dispatch_revision,d.response_due_at FROM alarm_responses a JOIN dispatch_jobs d ON d.company_id=a.company_id AND d.dispatch_id=a.dispatch_id WHERE a.company_id=:company AND d.responder_user_id=:actor AND a.closed_at IS NULL ORDER BY a.alarm_id DESC LIMIT 100",['company'=>$this->company(),'actor'=>$this->actor()]);return array_values(array_filter($rows,fn($r)=>$this->access->allowed($r['site_id'])));}
 public function respond(string $id,string $action,array $in):array {return $this->atomic(function()use($id,$action,$in){$this->fields($in,['expected_revision']);$r=$this->alarm($id);if(!$r['dispatch_id']||$r['closed_at']||!in_array($action,['accept','arrive'],true))throw HttpException::conflict('Alarm is not available for this response.');return $this->control->dispatchAction((string)$r['dispatch_id'],$action,$in,true);});}
 private function run(string $id):array {$r=$this->row('guard_transport_runs','run_id',$id);$this->access->requireSite($r['site_id']);return $r;}
 public function transport(array $in,bool $self=false):array {$this->fields($in,$self?[]:['site_id']);$p=['company'=>$this->company()];if($self)$p['employee']=$this->employee();else $p['site']=$this->access->requireSite($in['site_id']??null)['site_id'];$rows=$this->db->fetchAll('SELECT r.* FROM guard_transport_runs r WHERE r.company_id=:company'.($self?' AND EXISTS(SELECT 1 FROM guard_transport_passengers p WHERE p.company_id=r.company_id AND p.run_id=r.run_id AND p.employee_id=:employee)':' AND r.site_id=:site').' ORDER BY run_id DESC LIMIT 200',$p);$out=[];foreach($rows as$r){if(!$this->access->allowed($r['site_id']))continue;$p=['company'=>$this->company(),'run'=>$r['run_id']];if($self)$p['employee']=$this->employee();$r['passengers']=$this->db->fetchAll('SELECT * FROM guard_transport_passengers WHERE company_id=:company AND run_id=:run'.($self?' AND employee_id=:employee':'').' ORDER BY pickup_at,passenger_id',$p);$r['history']=$self?[]:$this->events('transport',$r['run_id']);$out[]=$r;}return $out;}
 public function createRun(array $in):array {return $this->atomic(function()use($in){$this->fields($in,['site_id','route_name','vehicle_registration','capacity','driver_user_id','departs_at','pickup_grace_minutes','notes']);$s=$this->access->requireSite($in['site_id']??null);$driver=$this->operator($in['driver_user_id']??null,$s['site_id'],'guard_transport.manage');$at=$this->at($in['departs_at']??null);if($at<=gmdate('Y-m-d H:i:s'))throw HttpException::unprocessable('Choose a future departure.');$this->db->execute('INSERT INTO guard_transport_runs(company_id,site_id,route_name,vehicle_registration,capacity,driver_user_id,departs_at,pickup_grace_minutes,notes) VALUES(:company,:site,:route,:vehicle,:capacity,:driver,:at,:grace,:notes)',['company'=>$this->company(),'site'=>$s['site_id'],'route'=>$this->text($in['route_name']??null,150),'vehicle'=>$this->text($in['vehicle_registration']??null,30),'capacity'=>$this->number($in['capacity']??null,1,100),'driver'=>$driver['user_id'],'at'=>$at,'grace'=>$this->number($in['pickup_grace_minutes']??null,1,120),'notes'=>$this->text($in['notes']??null,2000)]);return $this->created('transport_run');});}
 public function passenger(string $id,array $in):array {return $this->atomic(function()use($id,$in){$this->fields($in,['employee_id','pickup_point','pickup_at']);$r=$this->run($id);$e=$this->row('employees','employee_id',$in['employee_id']??null);$at=$this->at($in['pickup_at']??null);if($r['state']!=='PLANNED'||$e['employment_status']!=='ACTIVE'||$at<$r['departs_at']||strtotime($at.' UTC')>strtotime($r['departs_at'].' UTC')+12*3600)throw HttpException::conflict('Choose an active employee and pickup within 12 hours after route departure.');$p=['company'=>$this->company(),'run'=>$id];if((int)$this->db->fetch('SELECT COUNT(*) AS n FROM guard_transport_passengers WHERE company_id=:company AND run_id=:run',$p)['n']>=(int)$r['capacity'])throw HttpException::conflict('Vehicle manifest is full.');if($this->db->fetch('SELECT passenger_id FROM guard_transport_passengers WHERE company_id=:company AND run_id=:run AND employee_id=:employee',$p+['employee'=>$e['employee_id']]))throw HttpException::conflict('Employee is already on this manifest.');$this->db->execute('INSERT INTO guard_transport_passengers(company_id,run_id,employee_id,pickup_point,pickup_at) VALUES(:company,:run,:employee,:point,:at)',$p+['employee'=>$e['employee_id'],'point'=>$this->text($in['pickup_point']??null,300),'at'=>$at]);return $this->created('transport_passenger');});}
 public function transportAction(string $id,string $action,array $in):array {return $this->atomic(function()use($id,$action,$in){$this->fields($in,['expected_revision','notes','passenger_id']);$r=$this->run($id);$this->revision($r,$in);$notes=$this->text($in['notes']??null,1000);$state=$r['state'];if($action==='start'&&$state==='PLANNED'){if(!$this->db->fetch('SELECT passenger_id FROM guard_transport_passengers WHERE company_id=:company AND run_id=:run',['company'=>$this->company(),'run'=>$id])||$r['departs_at']>gmdate('Y-m-d H:i:s'))throw HttpException::conflict('A manifest and reached departure time are required.');$state='IN_PROGRESS';}elseif($action==='cancel'&&$state==='PLANNED')$state='CANCELLED';elseif(in_array($action,['board','alight','missed'],true)&&$state==='IN_PROGRESS'){$p=$this->row('guard_transport_passengers','passenger_id',$in['passenger_id']??null);if($action==='board'&&$this->row('employees','employee_id',$p['employee_id'])['employment_status']!=='ACTIVE')throw HttpException::forbidden('An inactive employee cannot board a new trip.');if((string)$p['run_id']!==$id)throw HttpException::notFound();$next=match($action){'board'=>'BOARDED','alight'=>'ALIGHTED','missed'=>'MISSED'};if(($action==='alight'&&$p['state']!=='BOARDED')||($action!=='alight'&&$p['state']!=='EXPECTED')||($action==='missed'&&strtotime($p['pickup_at'].' UTC')+(int)$r['pickup_grace_minutes']*60>time()))throw HttpException::conflict('Passenger state/time does not allow this action.');$this->db->execute('UPDATE guard_transport_passengers SET state=:state,boarded_at=:boarded,alighted_at=:alighted,recorded_by_user_id=:actor,notes=:notes WHERE company_id=:company AND passenger_id=:id',['state'=>$next,'boarded'=>$action==='board'?gmdate('Y-m-d H:i:s'):$p['boarded_at'],'alighted'=>$action==='alight'?gmdate('Y-m-d H:i:s'):$p['alighted_at'],'actor'=>$this->actor(),'notes'=>$notes,'company'=>$this->company(),'id'=>$p['passenger_id']]);}elseif($action==='finish'&&$state==='IN_PROGRESS'){if($this->db->fetch("SELECT passenger_id FROM guard_transport_passengers WHERE company_id=:company AND run_id=:run AND state IN ('EXPECTED','BOARDED')",['company'=>$this->company(),'run'=>$id]))throw HttpException::conflict('Confirm every pickup and drop-off before finishing.');$state='COMPLETED';}else throw HttpException::conflict('Transport action unavailable.');$this->db->execute('UPDATE guard_transport_runs SET state=:state,revision=revision+1 WHERE company_id=:company AND run_id=:id',['state'=>$state,'company'=>$this->company(),'id'=>$id]);$this->history('transport',$id,strtoupper($action),$notes);return ['state'=>$state];});}
}
